import { loadStripe } from "@stripe/stripe-js";
import React, { useEffect } from "react";
import toast from "react-hot-toast";
import { useDispatch, useSelector } from "react-redux";
import { useNavigate } from "react-router-dom";
import { addToCart } from "../../../slices/cartSlice";

const CourseDetailsCard = ({ course, setConfirmationModal }) => {
    const { token } = useSelector((state) => state.auth);
    const { user } = useSelector((state) => state.profile);
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const { cart } = useSelector((state) => state.cart);

    // ✅ Debugging: Check if `course` exists
    useEffect(() => {
        console.log("Course Data:", course);
    }, [course]);

    // ✅ Fix: Use default values to prevent NaN warnings
    const coursePrice = course?.price && !isNaN(parseFloat(course.price)) 
    ? `₹${parseFloat(course.price).toFixed(2)}` 
    : "N/A";
    const courseTitle = course?.title || "No Course Title";
    const courseInstructor = course?.instructor || "Unknown Instructor";

    // ✅ Fix: Ensure Stripe key exists before calling `loadStripe`
    const handleBuyCourse = async () => {
        console.log("Starting payment process...");

        if (!process.env.REACT_APP_STRIPE_PUBLISHABLE_KEY) {
            console.error("❌ Stripe Publishable Key is missing in .env file");
            toast.error("Stripe configuration error. Contact support.");
            return;
        }

        if (token && user?.accountType === "Student") {
            console.log("Initializing Stripe...");
            const stripe = await loadStripe(process.env.REACT_APP_STRIPE_PUBLISHABLE_KEY);

            if (!stripe) {
                console.error("❌ Failed to initialize Stripe");
                toast.error("Payment system error. Try again later.");
                return;
            }

            const body = {
                products: [{ ...course }],
                userId: user._id,
            };

            console.log("Creating checkout session...");
            try {
                const response = await fetch(`${process.env.REACT_APP_BASE_URL}/create-checkout-session`, {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify(body),
                });

                if (!response.ok) {
                    throw new Error(`HTTP Error! Status: ${response.status}`);
                }

                const session = await response.json();
                console.log("Session created:", session);

                if (session.id) {
                    console.log("Redirecting to Stripe Checkout...");
                    const result = await stripe.redirectToCheckout({ sessionId: session.id });

                    if (result.error) {
                        console.error("❌ Stripe Checkout Error:", result.error);
                        toast.error("Payment failed. Try again.");
                    }
                } else {
                    console.error("❌ Failed to retrieve session ID");
                    toast.error("Payment could not be initiated.");
                }
            } catch (error) {
                console.error("❌ Error processing payment:", error);
                toast.error("Payment request failed. Try again later.");
            }
        } else {
            setConfirmationModal(true);
        }
    };
    // ✅ Fix: Prevent crash if `course` is undefined
    if (!course) {
        return <p>Loading course details...</p>;
    }

    return (
        <div className="course-details-card">
            <h2>{courseTitle}</h2>
            <p>Instructor: {courseInstructor}</p>
            <p>Price: {coursePrice}</p>

            <button onClick={handleBuyCourse} className="buy-now-btn">
                Buy Now
            </button>

            {user && user.accountType === "Student" && !cart.find((item) => item._id === course._id) && (
                <button onClick={() => dispatch(addToCart(course))} className="add-to-cart-btn">
                    Add to Cart
                </button>
            )}
        </div>
    );
};

export default CourseDetailsCard;
